  {
    "name": "plan_camera_view",
    "description": "Calculate only; never move. relative requires frame=camera_optical, translation_m=[right,down,forward], rotation_rad=[roll,pitch,yaw]. Delegates loose get_observe_view endpoint checking; PARTIAL/fallback does not prove a safe full path. target requires exactly one target_name or target_cell_id and uses plan_next_best_view.",
    "inputSchema": {
      "type": "object",
      "properties": {
        "request_id": {
          "type": "string",
          "minLength": 1,
          "maxLength": 128,
          "pattern": "^[A-Za-z0-9_-]+$",
          "description": "Unique ID for a NEW task. Retry identical inputs with this same ID to find the same task; never replay unknown work with a new ID."
        },
        "mode": {
          "enum": [
            "relative",
            "target"
          ]
        },
        "translation_m": {
          "type": "array",
          "minItems": 3,
          "maxItems": 3,
          "items": {
            "type": "number"
          }
        },
        "rotation_rad": {
          "type": "array",
          "minItems": 3,
          "maxItems": 3,
          "items": {
            "type": "number"
          }
        },
        "frame": {
          "const": "camera_optical"
        },
        "target_name": {
          "type": "string",
          "minLength": 1,
          "maxLength": 256
        },
        "target_cell_id": {
          "type": "string",
          "minLength": 1,
          "maxLength": 256
        },
        "camera_distance_m": {
          "type": "number",
          "minimum": 0.1,
          "maximum": 1.0,
          "default": 0.45
        },
        "wait_seconds": {
          "type": "number",
          "minimum": 0,
          "maximum": 120,
          "default": 0,
          "description": "Optional bounded wait for this existing calculation; no polling loop."
        }
      },
      "required": [
        "request_id",
        "mode"
      ],
      "additionalProperties": false,
      "oneOf": [
        {
          "properties": {
            "mode": {
              "const": "relative"
            }
          },
          "required": [
            "translation_m",
            "rotation_rad",
            "frame"
          ],
          "not": {
            "anyOf": [
              {
                "required": [
                  "target_name"
                ]
              },
              {
                "required": [
                  "target_cell_id"
                ]
              }
            ]
          }
        },
        {
          "properties": {
            "mode": {
              "const": "target"
            }
          },
          "oneOf": [
            {
              "required": [
                "target_name"
              ],
              "not": {
                "required": [
                  "target_cell_id"
                ]
              }
            },
            {
              "required": [
                "target_cell_id"
              ],
              "not": {
                "required": [
                  "target_name"
                ]
              }
            }
          ],
          "not": {
            "anyOf": [
              {
                "required": [
                  "translation_m"
                ]
              },
              {
                "required": [
                  "rotation_rad"
                ]
              },
              {
                "required": [
                  "frame"
                ]
              }
            ]
          }
        }
      ]
    },
    "outputSchema": {
      "type": "object",
      "required": [
        "success",
        "state",
        "status"
      ],
      "properties": {
        "success": {
          "type": "boolean"
        },
        "state": {
          "enum": [
            "QUEUED",
            "RUNNING",
            "COMPLETED",
            "FAILED",
            "BLOCKED",
            "CANCEL_PENDING",
            "CANCELLED",
            "UNKNOWN"
          ]
        },
        "status": {
          "type": "string"
        },
        "task_id": {
          "type": "string"
        },
        "result": {
          "type": "object"
        },
        "blocker": {
          "type": "object"
        },
        "plan": {
          "type": "object"
        },
        "source_mode": {
          "type": "string"
        },
        "SIMULATED": {
          "type": "boolean"
        },
        "input_mode": {
          "type": "string"
        },
        "input_provenance": {
          "type": "object"
        }
      },
      "additionalProperties": true
    },
    "annotations": {
      "readOnlyHint": false,
      "destructiveHint": false,
      "idempotentHint": true,
      "openWorldHint": true
    },
    "_meta": {
      "taskInterface": true,
      "physicalDispatch": false
    }
  },
  {
    "name": "prepare_manipulation",
    "description": "Calculate only. grasp generates/selects/caches the full pool and confirms cache; grasp_lift additionally prepares/validates lift; pick_place requires destination and prepares/validates complete placement. Server owns all prerequisites. No physical execution. RUNNING requires get_task_status. Plan ID/revision exist only after an actual prepared plan is created. Retry same request_id to inspect same task.",
    "inputSchema": {
      "type": "object",
      "properties": {
        "request_id": {
          "type": "string",
          "minLength": 1,
          "maxLength": 128,
          "pattern": "^[A-Za-z0-9_-]+$",
          "description": "Unique ID for a NEW task. Retry identical inputs with this same ID to find the same task; never replay unknown work with a new ID."
        },
        "operation": {
          "enum": [
            "grasp",
            "grasp_lift",
            "pick_place"
          ]
        },
        "object_name": {
          "type": "string",
          "minLength": 1,
          "maxLength": 256
        },
        "destination": {
          "type": "string",
          "minLength": 1,
          "maxLength": 256
        },
        "lift_distance_m": {
          "type": "number",
          "exclusiveMinimum": 0,
          "maximum": 0.3,
          "default": 0.05
        },
        "wait_seconds": {
          "type": "number",
          "minimum": 0,
          "maximum": 120,
          "default": 0,
          "description": "Optional bounded wait for this existing calculation; no polling loop."
        }
      },
      "required": [
        "request_id",
        "operation",
        "object_name"
      ],
      "additionalProperties": false,
      "allOf": [
        {
          "if": {
            "properties": {
              "operation": {
                "const": "pick_place"
              }
            }
          },
          "then": {
            "required": [
              "destination"
            ]
          }
        }
      ]
    },
    "outputSchema": {
      "type": "object",
      "required": [
        "success",
        "state",
        "status"
      ],
      "properties": {
        "success": {
          "type": "boolean"
        },
        "state": {
          "enum": [
            "QUEUED",
            "RUNNING",
            "COMPLETED",
            "FAILED",
            "BLOCKED",
            "CANCEL_PENDING",
            "CANCELLED",
            "UNKNOWN"
          ]
        },
        "status": {
          "type": "string"
        },
        "task_id": {
          "type": "string"
        },
        "result": {
          "type": "object"
        },
        "blocker": {
          "type": "object"
        },
        "plan": {
          "type": "object"
        },
        "source_mode": {
          "type": "string"
        },
        "SIMULATED": {
          "type": "boolean"
        },
        "input_mode": {
          "type": "string"
        },
        "input_provenance": {
          "type": "object"
        }
      },
      "additionalProperties": true
    },
    "annotations": {
      "readOnlyHint": false,
      "destructiveHint": false,
      "idempotentHint": true,
      "openWorldHint": true
    },
    "_meta": {
      "taskInterface": true,
      "physicalDispatch": false
    }
  },
